#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MiniCut Patch 27: MEDIA-POOL PREVIEW (CapCut style) + LIVE VOICE RECORDING
==========================================================================

1. Media preview: click a media card once (not a drag) and the Player plays that file instead of the edit preview.
   - the media card is the progress bar: white vertical line = position; click / drag on the card to move it
   - Play/Pause (Space + Player button), previous/next frame, Home/End work on the media while it is previewed
   - stops when no card is selected, or when you go back to editing (timeline click, adding a clip, Record ...)
   - video / mp4 / mov / gif / mp3 ... work; a single picture is not previewed
   - the small preview box at the bottom of the media pool is removed
2. Recording: the take is drawn live on the timeline (growing audio clip + waveform), the playhead follows,
   the viewport meter shows the mic level. Microphone is chosen in Settings > General > Recording.

    python apply_27_media_preview_live_record.py            install
    python apply_27_media_preview_live_record.py --check    preview only
    python apply_27_media_preview_live_record.py --revert   undo last install
    python apply_27_media_preview_live_record.py --force    install over local edits
"""
import datetime, hashlib, json, os, py_compile, shutil, subprocess, sys

