REPLACE = {'minicut/render/recorder.py': {'base': '76551ce10bb967b052df760448b80f7b9971448340b9cad56a001f3abcde353c', 'new': '747bbada8baba5fc40d2263aa547a2e121ab3178ceb0558e58705a8254188036', 'content': '"""Voice recording into the project: the microphone is recorded to a WAV file in the asset folder (Recordings/).\nWhile recording, the level of every 10 ms is kept (peaks), so the timeline can draw the sound as it is recorded."""\nfrom ..shared.deps import *\nfrom ..shared.core import *\nfrom .audio import METER\n\ntry:\n    from PySide6.QtMultimedia import QAudioSource, QAudioFormat, QMediaDevices\nexcept Exception:\n    QAudioSource = None\n\n\ndef list_audio_inputs():\n    """[(name, id)] of the microphones this PC has. The id is what Settings stores."""\n    out = []\n    if QAudioSource is None: return out\n    try:\n        for d in QMediaDevices.audioInputs(): out.append((d.description(), bytes(d.id()).decode("utf-8", "ignore")))\n    except Exception: pass\n    return out\n\n\ndef _find_input(device_id):\n    """(device, found): the microphone with this id, else the system default."""\n    if device_id:\n        for d in QMediaDevices.audioInputs():\n            if bytes(d.id()).decode("utf-8", "ignore") == device_id: return d, True\n    return QMediaDevices.defaultAudioInput(), not device_id\n\n\nclass VoiceRecorder(QObject):\n    PEAKS_PER_SEC = 100\n\n    def __init__(self):\n        super().__init__(); self.src = None; self.io = None; self.chunks = []; self.rate = SR; self.ch = 2; self.frames = 0\n        self.fallback = False; self.device_name = ""; self._dt = np.dtype("<i2"); self._rest = b""; self._carry = np.zeros(0, np.float32)\n        self.peaks = np.zeros(2048, np.float32); self.npk = 0\n        self.timer = QTimer(self); self.timer.setInterval(25); self.timer.timeout.connect(self._pull)\n\n    def active(self): return self.src is not None\n    def seconds(self): return self.frames / float(self.rate or SR)\n    def peaks_view(self): return self.peaks[: self.npk]\n\n    def start(self, folder, device_id=""):\n        self.folder = folder\n        if QAudioSource is None: raise RuntimeError("Recording needs QtMultimedia, which is not available here.")\n        dev, found = _find_input(device_id); self.fallback = bool(device_id) and not found\n        if dev.isNull(): raise RuntimeError("No microphone was found.")\n        want = QAudioFormat(); want.setSampleRate(SR); want.setChannelCount(2); want.setSampleFormat(QAudioFormat.SampleFormat.Int16)\n        fmt = next((f for f in (want, dev.preferredFormat()) if dev.isFormatSupported(f)), dev.preferredFormat())\n        sf = fmt.sampleFormat(); SF = QAudioFormat.SampleFormat\n        self._dt = np.dtype({SF.UInt8: "u1", SF.Int16: "<i2", SF.Int32: "<i4", SF.Float: "<f4"}.get(sf, "<i2"))\n        if sf not in (SF.UInt8, SF.Int16, SF.Int32, SF.Float): fmt.setSampleFormat(SF.Int16)\n        self.rate = fmt.sampleRate(); self.ch = max(1, fmt.channelCount()); self.device_name = dev.description()\n        self.chunks = []; self.frames = 0; self._rest = b""; self._carry = np.zeros(0, np.float32); self.npk = 0\n        self.src = QAudioSource(dev, fmt); self.io = self.src.start()\n        if self.io is None:\n            self.src = None; raise RuntimeError("The microphone could not be opened (is another program using it?).")\n        self.timer.start()\n\n    def _to_int16(self, arr):\n        k = self._dt.kind; sz = self._dt.itemsize\n        if k == "f": x = np.clip(arr, -1.0, 1.0) * 32767.0\n        elif k == "u": x = (arr.astype(np.float32) - 128.0) * 256.0\n        elif sz == 4: x = arr.astype(np.float32) / 65536.0\n        else: return arr.astype(np.int16)\n        return x.astype(np.int16)\n\n    def _pull(self):\n        if self.io is None: return\n        data = self._rest + bytes(self.io.readAll())\n        if not data: return\n        frame = self._dt.itemsize * self.ch; n = len(data) // frame * frame\n        self._rest = data[n:]\n        if n == 0: return\n        a = self._to_int16(np.frombuffer(data[:n], self._dt).reshape(-1, self.ch))\n        if self.ch == 1: a = np.repeat(a, 2, axis=1)\n        a = np.ascontiguousarray(a[:, :2]); self.chunks.append(a); self.frames += len(a)\n        ab = np.abs(a.astype(np.int32))\n        METER["l"] = float(ab[:, 0].max()) / 32768.0; METER["r"] = float(ab[:, 1].max()) / 32768.0; METER["t"] = time.monotonic()    # level meter\n        hop = max(1, self.rate // self.PEAKS_PER_SEC)\n        self._carry = np.concatenate([self._carry, ab.max(axis=1).astype(np.float32)]); k = len(self._carry) // hop\n        if k:\n            blk = self._carry[: k * hop].reshape(k, hop).max(axis=1) / 32768.0; self._carry = self._carry[k * hop:]\n            if self.npk + k > len(self.peaks): self.peaks = np.concatenate([self.peaks, np.zeros(max(len(self.peaks), k), np.float32)])\n            self.peaks[self.npk: self.npk + k] = blk; self.npk += k\n\n    def _close(self):\n        self.timer.stop(); self._pull()\n        if self.src is not None: self.src.stop()\n        self.src = None; self.io = None\n\n    def discard(self):\n        """Stop and throw the take away."""\n        if self.src is None: return\n        self._close(); self.chunks = []\n\n    def stop(self):\n        """Finish the take. Returns the WAV path (stereo, 16 bit) or None if the take is too short."""\n        if self.src is None: return None\n        self._close()\n        arr = np.concatenate(self.chunks) if self.chunks else np.zeros((0, 2), np.int16); self.chunks = []\n        if len(arr) < self.rate // 4: return None\n        folder = os.path.join(self.folder, "Recordings"); os.makedirs(folder, exist_ok=True)\n        path = os.path.join(folder, "voice_%s.wav" % datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))\n        with wave.open(path, "wb") as w:\n            w.setnchannels(2); w.setsampwidth(2); w.setframerate(self.rate); w.writeframes(np.ascontiguousarray(arr, "<i2").tobytes())\n        return path\n'}}

NEW_FILES = {'minicut/workspace/media_preview.py': '"""Media-pool preview, like CapCut.\n\nClick a media card once (do not drag it) and the Player shows that file instead of the edit preview:\n  * the media card itself is the progress bar: a white vertical line shows where the file is, click / drag on the card to move it\n  * Play / Pause, previous / next frame, go to start / end (the normal shortcuts and the Player buttons) work on the media\n  * it stops when no media card is selected any more, or when you go back to editing (timeline click, adding a clip ...)\nWorks for video, GIF and audio files. A single picture has nothing to play, so it is not previewed.\n"""\nfrom ..shared.deps import *\nfrom ..shared.core import *\nfrom ..shared.icons import *\nfrom ..render.media import *\nfrom ..render.audio import *\n\nPREVIEW_KINDS = ("video", "gif", "audio")\n_ZOMBIES = set()          # decoder threads that were asked to stop and are still finishing (a running QThread must not be freed)\n\n\nclass PreviewDecoder(QThread):\n    """Decodes the previewed file\'s pictures off the GUI thread. Only the newest request is served, so a slow\n    disk or a big video drops pictures instead of falling behind (the sound / clock keeps the time)."""\n    ready = Signal(object)\n\n    def __init__(self, path, kind):\n        super().__init__(); self.path = path; self.kind = kind; self.cv = threading.Condition(); self.req = None\n        self.alive = True; self.fps = 30.0\n\n    def submit(self, t, max_w, max_h):\n        with self.cv: self.req = (float(t), float(max_w), float(max_h)); self.cv.notify()\n\n    def stop(self):\n        with self.cv: self.alive = False; self.cv.notify()\n\n    def _open(self):\n        if self.kind == "video":\n            src = VideoSource(self.path, False); self.fps = float(src.fps or 30.0); return src\n        return GifSource(self.path)\n\n    @staticmethod\n    def _qimage(fr, fmt):\n        fr = np.ascontiguousarray(fr); h, w = fr.shape[:2]\n        img = QImage(fr.data, w, h, fr.strides[0], fmt); img._keep = fr; return img\n\n    def run(self):\n        try: src = self._open()\n        except Exception as ex:\n            print("media preview:", ex); return\n        try:\n            while True:\n                with self.cv:\n                    while self.req is None and self.alive: self.cv.wait()\n                    if not self.alive: break\n                    (t, mw, mh), self.req = self.req, None\n                try:\n                    if self.kind == "video": fr = src.raw_frame(t); fmt = QImage.Format_BGR888\n                    else: fr = src.frame(t, 1.0); fmt = QImage.Format_ARGB32           # GIF frames are BGRA in memory\n                    h, w = fr.shape[:2]; s = min(1.0, mw / max(1, w), mh / max(1, h))\n                    if s < 0.98: fr = cv2.resize(fr, (max(1, int(w * s)), max(1, int(h * s))), interpolation=cv2.INTER_AREA)\n                    if self.alive: self.ready.emit(self._qimage(fr, fmt))\n                except Exception as ex: print("media preview frame:", ex)\n        finally:\n            try:\n                if hasattr(src, "close"): src.close()\n            except Exception: pass\n\n\nclass MediaPreviewMixin:\n    """Methods of the main window that drive the media-pool preview. State: self._mprev (None, or a dict)."""\n\n    # ---------------------------------------------------------------- helpers\n    def _mprev_duration(self, path, kind):\n        key = ("d", path); d = self.thumbs.cache.get(key)\n        if not d:\n            k, d = probe(path); d = float(d or 0.0)\n            if d > 0: self.thumbs.cache[key] = d\n        return float(d or 0.0)\n\n    def _mprev_timer_get(self):\n        t = getattr(self, "_mprev_timer", None)\n        if t is None: t = self._mprev_timer = QTimer(self); t.timeout.connect(self._mprev_tick)\n        return t\n\n    def _mprev_shim(self, m):\n        if m.get("shim") is None:\n            shim = copy.copy(self.proj); clip = make_clip("audio", m["path"], "mprev", 0.0, m["dur"], m["dur"])\n            shim.clips = [clip]; shim.tracks = [{"id": "mprev", "kind": "audio", "name": "mprev", "muted": False, "locked": False, "hidden": False}]\n            m["shim"] = shim\n        return m["shim"]\n\n    def _mprev_fps(self, m):\n        dec = m.get("dec")\n        return float(getattr(dec, "fps", 0) or m.get("fps") or 30.0) if dec is not None and m["kind"] == "video" else float(m.get("fps") or 30.0)\n\n    def _mprev_clock(self, m):\n        if not m["playing"]: return m["t"]\n        t = self.audio.clock() if m["audio_on"] else m["t0"] + (time.monotonic() - m["wall0"])\n        return max(0.0, min(m["dur"], t))\n\n    def _mprev_request(self, m):\n        dec = m.get("dec")\n        if dec is None or not hasattr(self, "viewport"): return\n        vp = self.viewport; dpr = vp.devicePixelRatioF()\n        dec.submit(min(m["t"], max(0.0, m["dur"] - 0.5 / self._mprev_fps(m))), max(64, vp.width() * dpr), max(64, vp.height() * dpr))\n\n    def _mprev_ui(self):\n        """Time readout and play icon of the Player; repaint of the card (the white line)."""\n        m = self._mprev\n        if m is None or not hasattr(self, "preview"): return\n        fps = self._mprev_fps(m)\n        self.preview.time.setText(fmt_time(m["t"], fps) + " / " + fmt_time(m["dur"], fps))\n        want = "pause" if m["playing"] else "play"\n        if getattr(self, "_play_icon", None) != want: self.preview.play_btn.setIcon(app_icon(want)); self._play_icon = want\n        if hasattr(self, "media"): self.media.list.repaint_path(m["path"])\n\n    def _mprev_after_move(self):\n        m = self._mprev\n        if m is None: return\n        m["frac"] = (m["t"] / m["dur"]) if m["dur"] > 0 else 0.0\n        self._mprev_request(m); self._mprev_ui()\n\n    def _mprev_frame(self, img):\n        if self._mprev is not None and hasattr(self, "viewport"): self.viewport.set_media_frame(img)\n\n    # ---------------------------------------------------------------- enter / leave\n    def enter_media_preview(self, path, kind, frac=0.0):\n        """Show a media-pool file in the Player (paused, at the clicked position). Returns False when it cannot be previewed."""\n        if kind not in PREVIEW_KINDS or not self.proj or not os.path.isfile(path) or getattr(self, "_rec", None):\n            if kind not in PREVIEW_KINDS: self.exit_media_preview()\n            return False\n        m = self._mprev\n        if m is not None and m["path"] == path: self._mprev_seek_frac(frac); return True\n        self._mprev_close()\n        if self.playing: self.stop_play()\n        dur = self._mprev_duration(path, kind)\n        if dur <= 0: return False\n        m = {"path": path, "kind": kind, "frac": 0.0, "t": 0.0, "dur": dur, "playing": False, "fps": float(self.proj.fps),\n             "dec": None, "shim": None, "audio_on": False, "t0": 0.0, "wall0": 0.0, "was_playing": False}\n        if kind in ("video", "gif"):\n            dec = PreviewDecoder(path, kind); dec.ready.connect(self._mprev_frame, Qt.QueuedConnection); m["dec"] = dec; dec.start()\n        if kind in ("video", "audio"): self.thumbs.wave(path)           # decode the sound now, so Play starts at once\n        try: self.thumbs.updated.connect(self._mprev_audio_check)\n        except Exception: pass\n        self._mprev = m\n        if hasattr(self, "viewport"): self.viewport.mimg = None\n        self._mprev_seek_frac(frac)\n        return True\n\n    def _mprev_close(self):\n        m = self._mprev\n        if m is None: return\n        self._mprev = None\n        self._mprev_timer_get().stop()\n        if m["playing"] or m["audio_on"]: self.audio.stop()\n        try: self.thumbs.updated.disconnect(self._mprev_audio_check)\n        except Exception: pass\n        dec = m.get("dec")\n        if dec is not None:\n            try: dec.ready.disconnect(self._mprev_frame)\n            except Exception: pass\n            dec.stop()\n            if not dec.isFinished():\n                _ZOMBIES.add(dec); dec.finished.connect(lambda d=dec: _ZOMBIES.discard(d))\n        if hasattr(self, "viewport"): self.viewport.mimg = None\n        if hasattr(self, "media"): self.media.list.repaint_path(m["path"])\n\n    def exit_media_preview(self, clear_selection=False):\n        """Back to the edit preview. clear_selection also un-selects the media card."""\n        had = self._mprev is not None\n        self._mprev_close()\n        if clear_selection and hasattr(self, "media"):\n            lst = self.media.list; lst.blockSignals(True); lst.clearSelection(); lst.setCurrentRow(-1); lst.blockSignals(False); lst.viewport().update()\n        if had:\n            if hasattr(self, "viewport"): self.viewport.update()\n            if self.proj: self.request_render(); self.refresh_ui()\n\n    def media_click(self, path, kind, frac=0.0):\n        """A single click on a media card (not a drag)."""\n        if kind in PREVIEW_KINDS: self.enter_media_preview(path, kind, frac)\n        else: self.exit_media_preview()\n\n    # ---------------------------------------------------------------- playing\n    def media_play(self):\n        m = self._mprev\n        if m is None or m["playing"]: return\n        if m["t"] >= m["dur"] - 0.02: self._mprev_set_t(0.0)\n        m["playing"] = True; m["t0"] = m["t"]; m["wall0"] = time.monotonic(); m["audio_on"] = False\n        self._mprev_audio_start(m, m["t"])\n        tm = self._mprev_timer_get(); tm.setInterval(self.frame_ms()); tm.start(); self._mprev_ui()\n\n    def media_pause(self):\n        m = self._mprev\n        if m is None or not m["playing"]: return\n        m["t"] = self._mprev_clock(m); m["playing"] = False; self._mprev_timer_get().stop()\n        if m["audio_on"]: self.audio.stop()\n        m["audio_on"] = False; self._mprev_after_move()\n\n    def media_toggle_play(self):\n        if self._mprev is None: return\n        self.media_pause() if self._mprev["playing"] else self.media_play()\n\n    def _mprev_audio_start(self, m, t):\n        if m["kind"] not in ("video", "audio"): return\n        if m["path"] not in AUDIO.peaks:\n            self.thumbs.wave(m["path"]); return         # still decoding in the background: the sound joins in when ready\n        self.audio.start(self._mprev_shim(m), t); m["audio_on"] = True\n\n    def _mprev_audio_check(self):\n        m = self._mprev\n        if m is not None and m["playing"] and not m["audio_on"] and m["path"] in AUDIO.peaks:\n            self._mprev_audio_start(m, self._mprev_clock(m))\n\n    def _mprev_tick(self):\n        m = self._mprev\n        if m is None or not m["playing"]: self._mprev_timer_get().stop(); return\n        t = self._mprev_clock(m)\n        if t >= m["dur"] - 1e-3:\n            self.media_pause(); self._mprev_set_t(m["dur"]); return          # reached the end: stay on the last picture\n        m["t"] = t; self._mprev_after_move()\n\n    # ---------------------------------------------------------------- moving\n    def _mprev_set_t(self, t):\n        m = self._mprev\n        if m is None: return\n        m["t"] = max(0.0, min(m["dur"], float(t)))\n        if m["playing"]:\n            m["t0"] = m["t"]; m["wall0"] = time.monotonic()\n            if m["audio_on"]: self.audio.start(self._mprev_shim(m), m["t"])\n        self._mprev_after_move()\n\n    def _mprev_seek_frac(self, frac):\n        m = self._mprev\n        if m is not None: self._mprev_set_t(max(0.0, min(1.0, float(frac))) * m["dur"])\n\n    def media_scrub_begin(self, frac):\n        """Mouse down on the media card: it is the progress bar. Playing is paused while the line is dragged."""\n        m = self._mprev\n        if m is None: return\n        m["was_playing"] = m["playing"]\n        if m["playing"]: self.media_pause()\n        self._mprev_seek_frac(frac)\n\n    def media_scrub(self, frac): self._mprev_seek_frac(frac)\n\n    def media_scrub_end(self):\n        m = self._mprev\n        if m is not None and m["was_playing"]: m["was_playing"] = False; self.media_play()\n\n    def media_step(self, d):\n        m = self._mprev\n        if m is None: return\n        self.media_pause(); self._mprev_set_t(m["t"] + d / self._mprev_fps(m))\n\n    def media_go(self, end):\n        m = self._mprev\n        if m is None: return\n        self.media_pause(); self._mprev_set_t(m["dur"] if end else 0.0)\n\n    def sc_guard(self, fn):\n        """Editing shortcuts (split, delete ...) do nothing while a media file is being previewed: the timeline is not on screen."""\n        def run(*a):\n            if self._mprev is not None: return\n            return fn()\n        return run\n\n    def sc_go(self, end):\n        if self._mprev is not None: self.media_go(end); return\n        self.seek((self.proj.duration() if self.proj else 0) if end else 0)\n', 'minicut/workspace/record_live.py': '"""Recording your voice with a live waveform on the timeline (like CapCut).\n\nRecord: the take is drawn on an audio track while you speak, the playhead moves along (the picture follows silently,\nso you can watch the video while you talk), and Stop turns it into a normal audio clip. The microphone is chosen in\nSettings > General > Recording.\n"""\nfrom ..shared.deps import *\nfrom ..shared.icons import *\nfrom ..shared.core import *\nfrom ..render.media import AUDIO\nfrom ..render.recorder import *\n\n\nclass RecordMixin:\n    def _rec_pick_track(self, start):\n        """(track, created): the first unlocked audio track that is free from `start` on, else a new audio track."""\n        P = self.proj\n        for tr in P.tracks:\n            if tr["kind"] == "audio" and not tr.get("locked") and not any(c["track"] == tr["id"] and c["start"] + c["dur"] > start - 1e-6 for c in P.clips):\n                return tr, False\n        return P.add_track("audio"), True\n\n    def _rec_button(self, on):\n        btn = getattr(getattr(self, "timeline_panel", None), "rec_btn", None)\n        if btn is not None: btn.label = "Stop" if on else "Record"; btn.setIconName("stop" if on else "mic"); btn.update()\n\n    def toggle_record(self):\n        """Record your voice: click to start, click again to stop. The take becomes an audio clip where it started."""\n        if not self.proj: return\n        if getattr(self, "recorder", None) is None: self.recorder = VoiceRecorder()\n        rec = self.recorder\n        if rec.active(): self.finish_record(); return\n        if getattr(self, "_mprev", None) is not None: self.exit_media_preview(clear_selection=True)\n        if self.playing: self.stop_play()\n        try: rec.start(self.settings["asset_folder"], self.settings["audio_input"])\n        except Exception as ex:\n            QMessageBox.warning(self, "MiniCut", "Could not start recording:\\n%s" % ex); return\n        start = self.t; tr, created = self._rec_pick_track(start)\n        self._rec = {"start": start, "track": tr["id"], "created": created, "n": 0}\n        tm = getattr(self, "_rec_timer", None)\n        if tm is None: tm = self._rec_timer = QTimer(self); tm.setInterval(33); tm.timeout.connect(self._rec_tick)\n        tm.start(); self._rec_button(True)\n        if created and hasattr(self, "timeline"): self.timeline.update_scroll()\n        if rec.fallback and hasattr(self, "toast"): self.toast.show_msg("The chosen microphone was not found. Using the system default: " + rec.device_name, 3500)\n        self._rec_tick()\n\n    def _rec_tick(self):\n        r = getattr(self, "_rec", None)\n        if r is None: return\n        self.t = r["start"] + self.recorder.seconds(); r["n"] += 1\n        tl = getattr(self, "timeline", None)\n        if tl is not None:\n            tl.update_scroll(); tl.follow(); tl.update()\n        if hasattr(self, "preview"): self.preview.time.setText(fmt_time(self.t, self.proj.fps) + " / " + fmt_time(max(self.proj.duration(), self.t), self.proj.fps))\n        if r["n"] % 3 == 0: self.request_render()     # the picture follows the playhead (about 10 times a second)\n\n    def finish_record(self, discard=False):\n        """Stop recording (if it is running) and put the take on the timeline."""\n        r = getattr(self, "_rec", None); rec = getattr(self, "recorder", None)\n        if r is None or rec is None or not rec.active(): self._rec = None; return\n        tm = getattr(self, "_rec_timer", None)\n        if tm is not None: tm.stop()\n        peaks = rec.peaks_view().copy()\n        if discard: rec.discard(); path = None\n        else: path = rec.stop()\n        self._rec = None; self._rec_button(False)\n        if path:\n            AUDIO.peaks[path] = peaks              # the timeline keeps showing the waveform it drew while recording\n            self.add_files([path], r["start"], r["track"])\n        else:\n            tr = self.proj.track(r["track"]) if self.proj else None\n            if r["created"] and tr is not None and not any(c["track"] == tr["id"] for c in self.proj.clips): self.proj.tracks.remove(tr)\n            if hasattr(self, "toast") and not discard: self.toast.show_msg("The recording was too short and was not kept.", 2500)\n            self.on_changed()\n        if hasattr(self, "timeline"): self.timeline.update_scroll(); self.timeline.update()\n'}

HERE = os.path.dirname(os.path.abspath(__file__))
BACKUP_ROOT = os.path.join(HERE, "_patch_backup")
PATCH_NAME = "media_preview_live_record"
try: sys.stdout.reconfigure(errors="replace")
except Exception: pass


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(HERE, *rel.split("/"))
def read(rel):
    p = path_of(rel)
    return open(p, "rb").read() if os.path.exists(p) else None
def say(msg=""): print(msg, flush=True)


def edited_text(rel, raw):
    info = EDITS[rel]
    text = raw.decode("utf-8"); crlf = "\r\n" in text; t = text.replace("\r\n", "\n")
    for old, new in info["edits"]:
        n = t.count(old)
        if n != 1: raise ValueError("%s: expected the patch text exactly once, found %d times" % (rel, n))
        t = t.replace(old, new, 1)
    return (t.replace("\n", "\r\n") if crlf else t).encode("utf-8")


def plan():
    rows, outputs = [], {}
    for rel, info in list(EDITS.items()) + list(REPLACE.items()):
        cur = read(rel)
        if cur is None:
            rows.append((rel, "missing", "file not found")); continue
        if norm_hash(cur) == info["new"]:
            rows.append((rel, "same", "already up to date")); continue
        if norm_hash(cur) != info["base"]:
            rows.append((rel, "edited", "differs from the version this patch was made for")); continue
        try:
            outputs[rel] = edited_text(rel, cur) if rel in EDITS else info["content"].encode("utf-8")
            rows.append((rel, "ok", "will be updated"))
        except ValueError as ex:
            rows.append((rel, "edited", str(ex)))
    for rel, src in NEW_FILES.items():
        cur = read(rel)
        if cur is None: rows.append((rel, "new", "will be created")); outputs[rel] = src.encode("utf-8")
        elif cur.decode("utf-8", "replace") == src: rows.append((rel, "same", "already up to date"))
        else: rows.append((rel, "edited", "already exists and differs"))
    return rows, outputs


def import_ok():
    code = "import os; os.environ['QT_QPA_PLATFORM']='offscreen'; import minicut.app"
    try:
        r = subprocess.run([sys.executable, "-c", code], cwd=HERE, capture_output=True, text=True, timeout=180)
        return r.returncode == 0, (r.stderr or r.stdout)[-1500:]
    except Exception as ex: return False, str(ex)


def latest_backup():
    if not os.path.isdir(BACKUP_ROOT): return None
    ds = sorted(d for d in os.listdir(BACKUP_ROOT) if os.path.exists(os.path.join(BACKUP_ROOT, d, "MANIFEST.json")))
    return os.path.join(BACKUP_ROOT, ds[-1]) if ds else None


def revert(bdir):
    man = json.load(open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8"))
    for rel in man["replaced"]: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in man["created"]:
        if os.path.exists(path_of(rel)): os.remove(path_of(rel))
    say("Restored %d file(s), removed %d new file(s) from %s" % (len(man["replaced"]), len(man["created"]), bdir))


def main():
    if not os.path.isfile(path_of("minicut/app.py")):
        say("ERROR: minicut/app.py not found.\nPut this file in the MiniCut folder (next to file.py) and run again."); return 2
    if "--revert" in sys.argv:
        b = latest_backup()
        if not b: say("No backup found in _patch_backup/."); return 1
        revert(b); return 0
    rows, outputs = plan()
    say("MiniCut Patch 27: media-pool preview + live voice recording\n")
    for rel, st, note in rows: say("  %-44s %s" % (rel, note))
    say()
    if "--check" in sys.argv: return 0
    if all(st == "same" for _, st, _ in rows): say("Nothing to do: already installed."); return 0
    if any(st == "missing" for _, st, _ in rows):
        say("STOPPED. File missing:\n  " + "\n  ".join(rel for rel, st, _ in rows if st == "missing")); return 3
    bad = [rel for rel, st, _ in rows if st == "edited"]
    if bad and "--force" not in sys.argv:
        say("STOPPED. Files differ from expected:\n  " + "\n  ".join(bad) +
            "\nRun with --force to continue anyway (files are backed up first).")
        return 3
    if bad:
        for rel in bad:
            try:
                if rel in EDITS: outputs[rel] = edited_text(rel, read(rel))
                elif rel in REPLACE: outputs[rel] = REPLACE[rel]["content"].encode("utf-8")
            except ValueError as ex: say("STOPPED: %s" % ex); return 3
    base_ok, _ = import_ok()
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); replaced, created = [], []
    os.makedirs(bdir, exist_ok=True)
    for rel in outputs:
        cur = path_of(rel)
        if os.path.exists(cur):
            dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(cur, dst); replaced.append(rel)
        else: created.append(rel)
    json.dump({"patch": PATCH_NAME, "created": created, "replaced": replaced},
              open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8"), indent=1)
    try:
        for rel, data in outputs.items():
            p = path_of(rel); os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "wb") as f: f.write(data)
            if rel.endswith(".py"): py_compile.compile(p, doraise=True)
    except Exception as ex:
        say("ERROR writing files: %s\nRestoring backup ..." % ex); revert(bdir); return 1
    for rel, info in list(EDITS.items()) + list(REPLACE.items()):
        if norm_hash(read(rel)) != info["new"]:
            say("ERROR: %s hash mismatch after write, restoring backup." % rel); revert(bdir); return 1
    ok, err = import_ok()
    if base_ok and not ok:
        say("Import failed after update, restoring backup.\n" + err); revert(bdir); return 1
    for sub in ("minicut/render", "minicut/workspace", "minicut/shared"):
        shutil.rmtree(os.path.join(path_of(sub), "__pycache__"), ignore_errors=True)
    say("Done. %d file(s) updated, %d created.  Backup: %s" % (len(replaced), len(created), bdir))
    say("Start MiniCut as usual.")
    say("To undo:  python apply_27_media_preview_live_record.py --revert")
    return 0


if __name__ == "__main__":
    code = 1
    try: code = main()
    except Exception as ex: say("Unexpected error: %r" % (ex,))
    if os.name == "nt" and "--no-pause" not in sys.argv: os.system("pause")
    sys.exit(code)
